// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 target = bound(blockNum, 1, 10_000);
        vm.roll(target);
        vm.warp(target * 1000 + 1);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        if (block.number % 15 == 0) {
            assertEq(address(c).balance, 0);
        } else {
            assertTrue(true);
        }
    }
}
